PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS learners(learner_id TEXT PRIMARY KEY, display_name TEXT NOT NULL, grade INTEGER NOT NULL CHECK(grade BETWEEN 1 AND 5), synthetic INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(session_id TEXT PRIMARY KEY, learner_id TEXT NOT NULL REFERENCES learners(learner_id), status TEXT NOT NULL CHECK(status IN ('ACTIVE','PAUSED','ENDED')), started_at TEXT NOT NULL, updated_at TEXT NOT NULL, ended_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS one_open_session_per_learner ON sessions(learner_id) WHERE status IN ('ACTIVE','PAUSED');
CREATE TABLE IF NOT EXISTS recommendations(recommendation_id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(session_id), learner_id TEXT NOT NULL, activity_id TEXT NOT NULL, game_type TEXT NOT NULL, area TEXT NOT NULL, tier TEXT NOT NULL, mode TEXT NOT NULL, reason_code TEXT NOT NULL, fallback_rule TEXT, policy_version TEXT NOT NULL, created_at TEXT NOT NULL, payload_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS question_instances(question_id TEXT PRIMARY KEY, recommendation_id TEXT NOT NULL REFERENCES recommendations(recommendation_id), session_id TEXT NOT NULL REFERENCES sessions(session_id), activity_id TEXT NOT NULL, game_type TEXT NOT NULL, tier TEXT NOT NULL, prompt TEXT NOT NULL, robot_task_json TEXT NOT NULL, expected_answer INTEGER NOT NULL CHECK(expected_answer BETWEEN 1 AND 25), status TEXT NOT NULL CHECK(status IN ('ACTIVE','ANSWERED','CANCELLED')), created_at TEXT NOT NULL, answered_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_question_per_session ON question_instances(session_id) WHERE status='ACTIVE';
CREATE TABLE IF NOT EXISTS interactions(event_id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(session_id), question_id TEXT NOT NULL REFERENCES question_instances(question_id), learner_id TEXT NOT NULL, activity_id TEXT NOT NULL, answer INTEGER, correct INTEGER CHECK(correct IN (0,1)), attempt_count INTEGER NOT NULL, timestamp TEXT NOT NULL, response_ms INTEGER, validation_status TEXT NOT NULL, payload_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS skill_profiles(learner_id TEXT NOT NULL REFERENCES learners(learner_id), game_type TEXT NOT NULL, area TEXT NOT NULL, valid_interactions INTEGER NOT NULL DEFAULT 0, correct_interactions INTEGER NOT NULL DEFAULT 0, skill_index REAL, last_assessed_at TEXT, updated_at TEXT NOT NULL, PRIMARY KEY(learner_id,game_type));
CREATE TABLE IF NOT EXISTS profile_exports(export_id TEXT PRIMARY KEY, learner_id TEXT NOT NULL, session_id TEXT, exported_at TEXT NOT NULL, schema_version TEXT NOT NULL, payload_json TEXT NOT NULL);
INSERT OR IGNORE INTO schema_migrations(version,applied_at) VALUES(1,datetime('now'));
